def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    alive = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)

    if budget <= 0:
        return 0.0

    if not alive:
        return float(min(budget, 20.0))

    prev_bids = []
    strong_prev = 0.0
    for opp in alive:
        prev = opp.get('previous_trace', {})
        b = prev.get('bid') if prev else None
        if b is not None:
            prev_bids.append(float(b))
            if float(b) > strong_prev:
                strong_prev = float(b)

    competitor_pressure = 0
    for opp in alive:
        if opp.get('budget', 0) >= 90:
            competitor_pressure += 1

    tight_supply = supply <= 17
    medium_supply = supply <= 20
    emergency = (hp <= 4) or (no_water >= 2)
    caution = (hp <= 6) or (no_water >= 1)

    if emergency:
        target = max(110.0, strong_prev + 3.0)
    elif tight_supply:
        target = max(78.0, min(108.0, strong_prev + 2.0))
    elif medium_supply:
        if caution:
            target = max(72.0, min(100.0, strong_prev * 0.82 + 4.0))
        else:
            target = 46.0 + 4.0 * competitor_pressure
    else:
        if caution:
            target = 62.0
        else:
            target = 28.0 + 3.0 * competitor_pressure

    if day >= 8 and hp >= 7 and no_water == 0:
        target *= 0.85

    if budget < target:
        if emergency:
            return float(budget)
        reserve = 0.0
        days_left = max(1, 10 - int(day) + 1)
        affordable = budget / days_left
        target = max(0.0, min(target, affordable * 1.4 + reserve))

    target = min(target, budget)
    if target < 0:
        target = 0.0
    return float(round(target, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 7
    DAILY_SALARY = 80
    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    if not alive_opponents:
        return min(my_status['budget'], 10)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    if my_status['hp'] <= 3:
        return min(my_status['budget'], DAILY_SALARY * 0.8)

    if yesterday_bids:
        max_prev = max(yesterday_bids)
        if max_prev > 60:
            return min(my_status['budget'], max_prev + 5)
        return min(my_status['budget'], 45)

    return min(my_status['budget'], 35)
